(()=>{'use strict';const canvas=document.getElementById('density-model'),status=document.getElementById('density-status'),gl=canvas.getContext('webgl2');let yaw=.4,pitch=.5,buffer,count=0,radius=1,positions,program;
if(!gl){status.textContent='3D rendering unavailable in this browser. The calibrated rotation plot remains available.';return;}
function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s;}
function setup(){program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,`#version 300 es
in vec3 position;uniform float yaw,pitch,radius,aspect;out vec3 world;void main(){world=position;float a=cos(yaw),b=sin(yaw),c=cos(pitch),d=sin(pitch);vec3 q=vec3(a*position.x-b*position.y,b*position.x+a*position.y,position.z);vec3 v=vec3(q.x,c*q.z-d*q.y,d*q.z+c*q.y);gl_Position=vec4(v.x/(radius*aspect),v.y/radius,-v.z/(4.0*radius),1.0);}`));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,`#version 300 es
precision highp float;in vec3 world;out vec4 color;void main(){vec3 n=normalize(cross(dFdx(world),dFdy(world)));float light=.3+.7*abs(dot(n,normalize(vec3(.3,-.5,1.0))));color=vec4(vec3(.94,.68,.25)*light,1.0);}`));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));buffer=gl.createBuffer();gl.enable(gl.DEPTH_TEST);gl.disable(gl.CULL_FACE);}
function draw(){if(gl.isContextLost())return;const width=Math.max(1,Math.round(canvas.clientWidth*devicePixelRatio)),height=Math.round(width*.55);canvas.width=width;canvas.height=height;gl.viewport(0,0,width,height);gl.clearColor(.06,.09,.14,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(program);gl.bindBuffer(gl.ARRAY_BUFFER,buffer);const a=gl.getAttribLocation(program,'position');gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,3,gl.FLOAT,false,0,0);for(const[k,v]of Object.entries({yaw,pitch,radius,aspect:width/height}))gl.uniform1f(gl.getUniformLocation(program,k),v);gl.drawArrays(gl.TRIANGLES,0,count);const overlay=document.getElementById('model-scale'),ns='http://www.w3.org/2000/svg';overlay.replaceChildren();const aspect=width/height,desired=radius*aspect*.4,power=10**Math.floor(Math.log10(desired)),length=[1,2,5,10].map(v=>v*power).filter(v=>v<=desired).at(-1)||power,pixels=length/(2*radius*aspect)*800;function mark(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;overlay.append(e);}mark('line',{x1:40,x2:40+pixels,y1:400,y2:400,stroke:'#ffffff','stroke-width':3});mark('text',{x:40,y:385,style:'font:28px system-ui'},length.toPrecision(2)+' kpc');overlay.dataset.scale=JSON.stringify({lengthKpc:length,x1:40,x2:40+pixels,viewWidth:800,radius,aspect});canvas.dataset.ready='true';}
function update(){try{const s=RotationReview.state,m=RotationDensity.densitySurface(s,.1,128,128);positions=new Float32Array(m.triangles.flatMap(t=>t.flatMap(i=>m.positions[i])));count=positions.length/3;radius=Math.max(.1,...m.positions.map(p=>Math.hypot(...p)))*1.1;gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,positions,gl.STATIC_DRAW);status.textContent=m.empty?'Zero disk mass: no disk density surface.':`Density ${m.density.toPrecision(5)} solar masses/kpc³. Maximum source radius ${(radius/1.1).toPrecision(4)} kpc. The halo is not drawn.`;window.RotationMeshReview={gl,positions,mesh:m,state:{...s},get radius(){return radius;},get program(){return program;}};draw();}catch(e){delete canvas.dataset.ready;status.textContent='Density model unavailable: '+e.message;}}
document.getElementById('turn').onclick=()=>{yaw+=.3;draw();};document.getElementById('tilt').onclick=()=>{pitch+=.25;draw();};document.getElementById('camera-reset').onclick=()=>{yaw=.4;pitch=.5;draw();};for(const input of document.querySelectorAll('#controls input'))input.addEventListener('change',update);for(const id of ['reset','degeneracy'])document.getElementById(id).addEventListener('click',update);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();delete canvas.dataset.ready;status.textContent='3D context lost; waiting for recovery.';});canvas.addEventListener('webglcontextrestored',()=>{setup();update();});new ResizeObserver(draw).observe(canvas);try{setup();update();}catch(e){status.textContent=e.message;}})();
